// Webhook body로 { "events": [ { date, start, end, name, description } ] } 를 보내면 그 목록을 등록하고,
// 없으면 아래 기본 일정(홍길동 11월 일정 6건)을 등록한다. 제목 형식: [일정명] HH:MM ~ HH:MM (KST)
const DEFAULTS = [
  { date: '2026-11-11', start: '10:00', end: '11:00', name: '기획팀 킥오프 회의', description: '기획팀과 신규 프로젝트 방향성을 정하는 킥오프 회의' },
  { date: '2026-11-12', start: '14:00', end: '15:00', name: '부서 회의', description: '하반기 성과를 점검하는 부서 회의' },
  { date: '2026-11-13', start: '16:00', end: '17:00', name: '외부 협력사 미팅', description: '외부 협력사와의 신규 사업 미팅 - 관련 제안서를 미리 챙길 것' },
  { date: '2026-11-17', start: '15:00', end: '16:00', name: '클라이언트 계약 미팅', description: '클라이언트와의 본 계약 체결을 위한 주요 미팅' },
  { date: '2026-11-19', start: '17:00', end: '18:00', name: '부서별 주간 업무 보고회', description: '부서별 주간 업무 보고회' },
  { date: '2026-11-20', start: '14:00', end: '15:00', name: '4분기 실적 공유 워크숍', description: '전사 차원의 4분기 실적 공유 워크숍' },
];
const src = $input.first().json;
const list = (src.body && Array.isArray(src.body.events) && src.body.events.length) ? src.body.events : DEFAULTS;
// KST(UTC+9) → UTC RFC3339
const toUtc = (date, hm) => {
  const [y, m, d] = date.split('-').map(Number);
  const [h, mi] = hm.split(':').map(Number);
  return new Date(Date.UTC(y, m - 1, d, h - 9, mi)).toISOString().slice(0, 19) + 'Z';
};
return list.map((e) => {
  const title = `[${e.name}] ${e.start} ~ ${e.end}`.slice(0, 50);
  const event = {
    title,
    time: { start_at: toUtc(e.date, e.start), end_at: toUtc(e.date, e.end), time_zone: 'Asia/Seoul', all_day: false, lunar: false },
    description: e.description || '',
    reminders: [30],
  };
  return { json: { title, event: JSON.stringify(event) } };
});
